function cameraUpdate(){const aspect=wrap.clientWidth/wrap.clientHeight;const span=Math.max(1, 1.02/aspect)*(state.layout==='studio'?5.2:6.4)/zoom;camera.left=-span*aspect;camera.right=span*aspect;camera.top=span;camera.bottom=-span;const elev=topView?1.55:elevation;camera.position.set(Math.sin(angle)*15*Math.cos(elev),15*Math.sin(elev),Math.cos(angle)*15*Math.cos(elev));camera.lookAt(0,.4,0);camera.updateProjectionMatrix();updateWalls()}
